<?php
declare(strict_types=1);namespace App\Http\Controllers\Finance;use App\Http\Controllers\Controller;use App\Models\{AcademicYear,Classroom,Semester,Student};use App\Models\Finance\{StudentInvoice,StudentPayment};use Illuminate\Http\Request;class FinanceReportController extends Controller{public function __invoke(Request $r){$iq=StudentInvoice::with('student.activeClassroomMembership.classroom');$pq=StudentPayment::with(['student.activeClassroomMembership.classroom','invoice']);foreach(['academic_year_id','semester_id','status','student_id'] as $f)if($r->filled($f))$iq->where($f,$r->$f);if($r->filled('month')){$iq->whereMonth('billing_month',$r->month);$pq->whereMonth('paid_at',$r->month);}if($r->filled('classroom_id')){foreach([$iq,$pq] as $q)$q->whereHas('student.activeClassroomMembership',fn($x)=>$x->where('classroom_id',$r->classroom_id));}$payments=$pq->latest('paid_at')->limit(200)->get();return view('finance.reports.index',['invoices'=>$iq->latest()->limit(200)->get(),'payments'=>$payments,'byMethod'=>$payments->groupBy('payment_method')->map->sum('amount'),'byMonth'=>$payments->groupBy(fn($p)=>$p->paid_at->format('Y-m'))->map->sum('amount'),'years'=>AcademicYear::all(),'semesters'=>Semester::all(),'classrooms'=>Classroom::all(),'students'=>Student::orderBy('full_name')->get()]);}}
